content.content:
1	// Tập 7 · C3 · phần chung của năm đoạn: dựng trang, "Tessa + nhà", the stack (W2, bó = một năm của khoản dự phòng), khung khoá, lớp bắt buộc, nhãn.
2	// Mốc giờ chỉ từ spine.json của đoạn; hằng số ở đây = hình học + độ dài hiệu ứng chung. Số trên hình chỉ qua claims.json (CL[id].display).
3	import * as THREE from 'three';
4	import { Studio, Person, House, Stack, setOpacity } from '/toolkit/factory/world/lib3d.js';
5	import { Camera, Stage, loadJSON, fonts, C, ease } from '/toolkit/factory/world/core.js';
6	
7	export const POP = 0.2, PLATE = '#0B0E13', FIG = '#C9D3E2';
8	export const kf = (k, t) => { if (!k || !k.length) return 0; if (t <= k[0][0]) return k[0][1];
9	  for (let i = 1; i < k.length; i++) if (t <= k[i][0]) { const [a, x] = k[i - 1], [b, y] = k[i]; return b > a ? x + (y - x) * (t - a) / (b - a) : y; }
10	  return k[k.length - 1][1]; };
11	// hiện từ mốc a (dốc POP), tắt từ mốc z (dốc 0,3 s) nếu có
12	export const show = (t, a, z = Infinity) => ease(t, a - 0.05, a + POP) * (1 - ease(t, z, z + 0.3));
13	
14	export async function setup(seg, res, poses, { shadowBox = 14 } = {}) {
15	  const [S, CL] = await Promise.all([loadJSON(seg + 'spine.json'), loadJSON('/episodes/ep007/world/claims.json')]);
16	  await fonts();
17	  const cue = {}; for (const b of S.beats) cue[b.id] = { ...b.cues, t0: b.t0, t1: b.t1 };
18	  const st = Stage(res), scene = new THREE.Scene(), { floor } = Studio(scene, { shadowBox });
19	  const D = (k) => CL[k].display;
20	  return { S, CL, D, cue, st, O: st.O, renderer: st.renderer, scene, floor, CAM: Camera(poses, S.moves) };
21	}
22	
23	// Tessa (W4, không mặt, ILLUSTRATIVE) đứng trước-trái căn nhà của cô (W1); nhà = ink-ish vật liệu kênh, không phải dữ liệu
24	export function home(scene, { x = 0, z = 0, w = 1.6, h = 1.15, side = -1 } = {}) {
25	  const house = House({ w }); house.position.set(x, 0, z); scene.add(house);
26	  const person = Person({ h, color: FIG }); person.position.set(x + side * (w / 2 + 0.6), 0, z + 0.45); scene.add(person);
27	  person.userData.checks = { role: 'mark', char: 'Tessa', key: 'person-tessa' };
28	  return { house, person, x, z, w, h };
29	}
30	export function nameTag(O, hm, a = 1, o = {}) {
31	  const [hx, hy] = O.toScreen(hm.person.position.x, hm.h + 0.12, hm.person.position.z);
32	  return label(O, 'Tessa · ILLUSTRATIVE', hx + (o.dx || 0), hy - 24 + (o.dy || 0), { align: 'center', kind: 'name', px: 48, w: 600, alpha: a, char: 'Tessa' });
33	}
34	
35	// the stack (W2): bó mệnh giá CỐ ĐỊNH = một năm của khoản dự phòng (extra_vs15_total_now / 15 ≈ 12 × $120); 15 bó = $21,622.
36	// Bó = warn (beats.md Colour roles: "warn = the price of the fallback (the stack's bills)").
37	export const BUNDLE_TH = 0.17;
38	export function theStack(scene, G, { x, z = 0 }) {
39	  const s = Stack({ unitUsd: G.bundle_usd / BUNDLE_TH, bundleUsd: G.bundle_usd, w: 0.9, d: 0.6, maxUsd: G.stack_total * 1.05 });
40	  s.position.set(x, 0, z); scene.add(s); s.userData.checks = { role: 'bar', series: 'stack', key: 'the-stack' };
41	  return s;
42	}
43	export const stackSet = (s, usd) => { s.set({ usd, warnAboveUsd: -1 }); s.userData.checks.value = +usd.toFixed(2); return usd / s.userData.unitUsd; };
44	
45	// N1 đường tháng chạy từ nhà Tessa (s21-track, s23-track dùng chung hình học + tư thế máy): nhà bên trái, cột-năm nối nhau sang phải,
46	// tháng 1 ở mép trước. Đồ thị = nhìn gần thẳng xuống mặt lưới (nghiêng 19°, tiêu cự dài) → lưới đọc như lịch 15 cột × 12 ô.
47	export const TRACK_POSES = {
48	  wT0: { pos: [-4.6, 3.4, 6.8], tgt: [2.4, 0, -1.8], fov: 40, chart: 0 },
49	  wT: { pos: [-3.4, 4.2, 5.4], tgt: [2.6, 0, -2.0], fov: 40, chart: 0 },
50	  cT: { pos: [2.45, 13.2, 5.1], tgt: [2.45, 0, -2.0], fov: 31, chart: 1 },
51	};
52	export async function trackWorld(scene, MonthTrack) {
53	  const hm = home(scene, { x: -1.55, z: -1.4, side: 1 });
54	  hm.person.position.set(-1.2, 0, 0.75);
55	  const track = MonthTrack({ name: 'tessa' }); track.position.set(0, 0, 0); scene.add(track);
56	  return { hm, track };
57	}
58	
59	// chế độ đồ thị: sàn + sương lùi đi (như Tập 5/6)
60	export function modeLook(scene, floor, cw) { floor.material.opacity = 1 - 0.85 * cw; scene.fog.near = 30 + 120 * cw; scene.fog.far = 80 + 220 * cw; }
61	
62	// lớp bắt buộc (như c3kit.js Tập 6): ILLUSTRATIVE (mọi khung có Tessa), nguồn + "US only · history, not a forecast" (mọi khung)
63	export function chrome(O) { O.chrome({ illus: true, src: 'Freddie Mac weekly mortgage survey', hist: true }); }
64	
65	// ngoặc ngang (nét lớp phủ, toạ độ thiết kế); tick > 0 = chân xuống, < 0 = chân lên
