      for (let i = 0; i <= 16; i++) { const [x, y, z] = path(trail.k, (trail.p * i) / 16), [sx, sy] = O.toScreen(x, y, z); i ? c.lineTo(sx, sy) : c.moveTo(sx, sy); }
      c.stroke(); c.restore();
